package com.geprofittracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Units;

@ConfigGroup("geprofittracker")
public interface GeProfitTrackerConfig extends Config
{
	@ConfigItem(
		position = 1,
		keyName = "autoTrackGePurchases",
		name = "Auto-track GE Purchases",
		description = "Automatically add items to tracking when a purchase is completed on the Grand Exchange"
	)
	default boolean autoTrackGePurchases()
	{
		return true;
	}

	@ConfigItem(
		position = 2,
		keyName = "priceUpdateInterval",
		name = "Price Update Interval",
		description = "How often current item prices should be refreshed (in minutes)"
	)
	@Units(Units.MINUTES)
	default int priceUpdateInterval()
	{
		return 10;
	}

	@ConfigItem(
		position = 3,
		keyName = "accountForGeTax",
		name = "Account for GE Tax",
		description = "Deduct 1% GE tax (capped at 5m per item) when calculating current value and profit/loss"
	)
	default boolean accountForGeTax()
	{
		return false;
	}
}

package com.geprofittracker;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

public final class GeProfitTrackerIcon
{
	private GeProfitTrackerIcon()
	{
	}

	public static BufferedImage create()
	{
		BufferedImage image = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// Gold coin base
		g.setColor(new Color(218, 165, 32));
		g.fillOval(3, 3, 26, 26);

		// Outer coin rim
		g.setColor(new Color(255, 215, 0));
		g.drawOval(3, 3, 26, 26);

		// Inner darker accent ring
		g.setColor(new Color(180, 130, 20));
		g.drawOval(6, 6, 20, 20);

		// Upward trending arrow / chart line in bright green
		g.setColor(new Color(40, 215, 70));
		g.drawLine(8, 22, 14, 16);
		g.drawLine(14, 16, 18, 19);
		g.drawLine(18, 19, 24, 11);

		// Arrow head pointing top right
		g.fillPolygon(
			new int[]{24, 19, 24},
			new int[]{11, 12, 17},
			3
		);

		g.dispose();
		return image;
	}
}

package com.geprofittracker;

import com.geprofittracker.ui.GeProfitTrackerPanel;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@PluginDescriptor(
	name = "GE Profit Tracker",
	description = "Tracks GE purchases, monitors prices periodically, and calculates profit or loss in real-time",
	tags = {"grand exchange", "ge", "flipping", "profit", "merch", "tracker", "price"},
	enabledByDefault = true
)
@Singleton
public class GeProfitTrackerPlugin extends Plugin
{
	public static final String CONFIG_GROUP = "geprofittracker";
	public static final String CONFIG_ITEMS_KEY = "trackedItems";

	@Inject
	private Client client;

	@Inject
	private ClientToolbar toolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private GeProfitTrackerConfig config;

	@Inject
	private Gson gson;

	@Inject
	private ScheduledExecutorService executor;

	private GeProfitTrackerPanel panel;
	private NavigationButton navButton;

	private final List<TrackedItem> trackedItems = Collections.synchronizedList(new ArrayList<>());
	private ScheduledFuture<?> priceUpdateTask;
	private long lastPriceUpdateTime = 0;

	// Internal state cache for 8 GE slots to detect buy completion
	private final OfferStateSnapshot[] lastOfferStates = new OfferStateSnapshot[8];

	private static class OfferStateSnapshot
	{
		final int itemId;
		final GrandExchangeOfferState state;
		final int quantitySold;
		final long spent;

		OfferStateSnapshot(int itemId, GrandExchangeOfferState state, int quantitySold, long spent)
		{
			this.itemId = itemId;
			this.state = state;
			this.quantitySold = quantitySold;
			this.spent = spent;
		}
	}

	@Provides
	GeProfitTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GeProfitTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadTrackedItems();

		panel = new GeProfitTrackerPanel(this, itemManager, clientThread);
		navButton = NavigationButton.builder()
			.tooltip("GE Profit Tracker")
			.icon(GeProfitTrackerIcon.create())
			.priority(6)
			.panel(panel)
			.build();

		toolbar.addNavigation(navButton);

		// Initial price update check dispatched onto clientThread
		updatePricesNow();

		// Schedule periodic price refresh (default 10 minutes)
		restartPriceUpdateScheduler();
	}

	@Override
	protected void shutDown()
	{
		if (priceUpdateTask != null && !priceUpdateTask.isDone())
		{
			priceUpdateTask.cancel(true);
			priceUpdateTask = null;
		}

		if (navButton != null)
		{
			toolbar.removeNavigation(navButton);
			navButton = null;
		}

		saveTrackedItems();
		trackedItems.clear();
		panel = null;
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		if (!config.autoTrackGePurchases())
		{
			return;
		}

		int slot = event.getSlot();
		if (slot < 0 || slot >= lastOfferStates.length)
		{
			return;
		}

		GrandExchangeOffer offer = event.getOffer();
		if (offer == null)
		{
			return;
		}

		GrandExchangeOfferState state = offer.getState();
		OfferStateSnapshot previous = lastOfferStates[slot];

		// Check if a buy offer has progressed or finished
		if (state == GrandExchangeOfferState.BOUGHT)
		{
			int prevQuantitySold = (previous != null && previous.itemId == offer.getItemId()) ? previous.quantitySold : 0;
			long prevSpent = (previous != null && previous.itemId == offer.getItemId()) ? previous.spent : 0;

			int newQuantity = offer.getQuantitySold() - prevQuantitySold;
			long newSpent = offer.getSpent() - prevSpent;

			if (newQuantity > 0 && newSpent > 0)
			{
				long unitPrice = Math.round((double) newSpent / newQuantity);
				handleGePurchase(offer.getItemId(), newQuantity, unitPrice);
			}
			else if (previous == null || previous.state != GrandExchangeOfferState.BOUGHT)
			{
				// Entire offer was bought
				int totalQuantity = offer.getQuantitySold();
				long totalSpent = offer.getSpent();
				if (totalQuantity > 0 && totalSpent > 0)
				{
					long unitPrice = Math.round((double) totalSpent / totalQuantity);
					handleGePurchase(offer.getItemId(), totalQuantity, unitPrice);
				}
			}
		}
		else if (state == GrandExchangeOfferState.CANCELLED_BUY)
		{
			// Check if any items were bought before cancellation
			int prevQuantitySold = (previous != null && previous.itemId == offer.getItemId()) ? previous.quantitySold : 0;
			long prevSpent = (previous != null && previous.itemId == offer.getItemId()) ? previous.spent : 0;

			int newQuantity = offer.getQuantitySold() - prevQuantitySold;
			long newSpent = offer.getSpent() - prevSpent;

			if (newQuantity > 0 && newSpent > 0)
			{
				long unitPrice = Math.round((double) newSpent / newQuantity);
				handleGePurchase(offer.getItemId(), newQuantity, unitPrice);
			}
		}

		// Update slot cache
		if (state == GrandExchangeOfferState.EMPTY)
		{
			lastOfferStates[slot] = null;
		}
		else
		{
			lastOfferStates[slot] = new OfferStateSnapshot(offer.getItemId(), state, offer.getQuantitySold(), offer.getSpent());
		}
	}

	private void handleGePurchase(int itemId, int quantity, long unitPrice)
	{
		clientThread.invokeLater(() -> {
			ItemComposition comp = itemManager.getItemComposition(itemId);
			String name = comp != null ? comp.getName() : "Item " + itemId;
			long currentPrice = itemManager.getItemPrice(itemId);
			if (currentPrice <= 0)
			{
				currentPrice = unitPrice;
			}

			addTrackedItem(itemId, name, quantity, unitPrice, currentPrice);
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals(CONFIG_GROUP))
		{
			return;
		}

		if (event.getKey().equals("priceUpdateInterval"))
		{
			restartPriceUpdateScheduler();
		}
		else if (event.getKey().equals("accountForGeTax"))
		{
			if (panel != null)
			{
				SwingUtilities.invokeLater(panel::rebuild);
			}
		}
	}

	public void restartPriceUpdateScheduler()
	{
		if (priceUpdateTask != null && !priceUpdateTask.isDone())
		{
			priceUpdateTask.cancel(false);
		}

		int intervalMinutes = Math.max(1, config.priceUpdateInterval());
		priceUpdateTask = executor.scheduleAtFixedRate(
			this::updatePricesNow,
			intervalMinutes,
			intervalMinutes,
			TimeUnit.MINUTES
		);
	}

	public void updatePricesNow()
	{
		if (trackedItems.isEmpty())
		{
			lastPriceUpdateTime = System.currentTimeMillis();
			if (panel != null)
			{
				SwingUtilities.invokeLater(panel::rebuild);
			}
			return;
		}

		clientThread.invokeLater(() -> {
			synchronized (trackedItems)
			{
				long now = System.currentTimeMillis();
				for (TrackedItem item : trackedItems)
				{
					long currentPrice = itemManager.getItemPrice(item.getItemId());
					if (currentPrice > 0)
					{
						item.setCurrentPrice(currentPrice);
						item.setLastUpdatedTime(now);
					}
				}
				lastPriceUpdateTime = now;
			}

			saveTrackedItems();

			if (panel != null)
			{
				SwingUtilities.invokeLater(panel::rebuild);
			}
		});
	}

	public void addTrackedItem(int itemId, String name, int quantity, long purchasePrice, long currentPrice)
	{
		TrackedItem newItem = new TrackedItem(itemId, name, quantity, purchasePrice, currentPrice);
		trackedItems.add(0, newItem); // Add at top
		saveTrackedItems();

		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::rebuild);
		}
	}

	public void removeItem(TrackedItem item)
	{
		trackedItems.remove(item);
		saveTrackedItems();

		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::rebuild);
		}
	}

	public void clearAllItems()
	{
		trackedItems.clear();
		saveTrackedItems();

		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::rebuild);
		}
	}

	public List<TrackedItem> getTrackedItems()
	{
		return new ArrayList<>(trackedItems);
	}

	public boolean isAccountForGeTax()
	{
		return config.accountForGeTax();
	}

	public long getLastPriceUpdateTime()
	{
		return lastPriceUpdateTime;
	}

	private void saveTrackedItems()
	{
		try
		{
			String json = gson.toJson(trackedItems);
			configManager.setConfiguration(CONFIG_GROUP, CONFIG_ITEMS_KEY, json);
		}
		catch (Exception ignored)
		{
		}
	}

	private void loadTrackedItems()
	{
		try
		{
			String json = configManager.getConfiguration(CONFIG_GROUP, CONFIG_ITEMS_KEY);
			if (json != null && !json.trim().isEmpty())
			{
				Type type = new TypeToken<List<TrackedItem>>() {}.getType();
				List<TrackedItem> loaded = gson.fromJson(json, type);
				if (loaded != null)
				{
					trackedItems.clear();
					trackedItems.addAll(loaded);
				}
			}
		}
		catch (Exception ignored)
		{
		}
	}
}

package com.geprofittracker;

import java.util.Objects;
import java.util.UUID;

public class TrackedItem
{
	private final String id;
	private final int itemId;
	private final String name;
	private int quantity;
	private long purchasePrice; // Unit buy price
	private long currentPrice;  // Current market unit price
	private long lastUpdatedTime;
	private long addedTime;

	public TrackedItem(int itemId, String name, int quantity, long purchasePrice, long currentPrice)
	{
		this(UUID.randomUUID().toString(), itemId, name, quantity, purchasePrice, currentPrice, System.currentTimeMillis(), System.currentTimeMillis());
	}

	public TrackedItem(String id, int itemId, String name, int quantity, long purchasePrice, long currentPrice, long lastUpdatedTime, long addedTime)
	{
		this.id = id != null ? id : UUID.randomUUID().toString();
		this.itemId = itemId;
		this.name = name;
		this.quantity = quantity;
		this.purchasePrice = purchasePrice;
		this.currentPrice = currentPrice;
		this.lastUpdatedTime = lastUpdatedTime;
		this.addedTime = addedTime;
	}

	public String getId()
	{
		return id;
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getName()
	{
		return name;
	}

	public int getQuantity()
	{
		return quantity;
	}

	public void setQuantity(int quantity)
	{
		this.quantity = quantity;
	}

	public long getPurchasePrice()
	{
		return purchasePrice;
	}

	public void setPurchasePrice(long purchasePrice)
	{
		this.purchasePrice = purchasePrice;
	}

	public long getCurrentPrice()
	{
		return currentPrice;
	}

	public void setCurrentPrice(long currentPrice)
	{
		this.currentPrice = currentPrice;
	}

	public long getLastUpdatedTime()
	{
		return lastUpdatedTime;
	}

	public void setLastUpdatedTime(long lastUpdatedTime)
	{
		this.lastUpdatedTime = lastUpdatedTime;
	}

	public long getAddedTime()
	{
		return addedTime;
	}

	public long getTotalPurchaseCost()
	{
		return purchasePrice * (long) quantity;
	}

	public long getTotalCurrentValue(boolean accountForTax)
	{
		long unitValue = currentPrice;
		if (accountForTax)
		{
			long taxPerItem = Math.min(5_000_000L, (long) Math.floor(currentPrice * 0.01));
			unitValue = Math.max(0, currentPrice - taxPerItem);
		}
		return unitValue * (long) quantity;
	}

	public long getProfitLoss(boolean accountForTax)
	{
		return getTotalCurrentValue(accountForTax) - getTotalPurchaseCost();
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o) return true;
		if (o == null || getClass() != o.getClass()) return false;
		TrackedItem that = (TrackedItem) o;
		return Objects.equals(id, that.id);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(id);
	}
}

package com.geprofittracker.ui;

import com.geprofittracker.GeProfitTrackerPlugin;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.GridLayout;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.DefaultListCellRenderer;
import javax.swing.DefaultListModel;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ListSelectionModel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.http.api.item.ItemPrice;

public class AddItemDialog extends JDialog
{
	private final GeProfitTrackerPlugin plugin;
	private final ItemManager itemManager;
	private final ClientThread clientThread;

	private final JTextField searchField = new JTextField();
	private final DefaultListModel<ItemPrice> listModel = new DefaultListModel<>();
	private final JList<ItemPrice> searchResultsList = new JList<>(listModel);
	private final JTextField quantityField = new JTextField("1");
	private final JTextField priceField = new JTextField();

	private ItemPrice selectedItem = null;

	public AddItemDialog(Component parent, GeProfitTrackerPlugin plugin, ItemManager itemManager, ClientThread clientThread)
	{
		super(SwingUtilities.getWindowAncestor(parent), "Add Item to Track", ModalityType.APPLICATION_MODAL);
		this.plugin = plugin;
		this.itemManager = itemManager;
		this.clientThread = clientThread;

		setSize(340, 480);
		setLocationRelativeTo(parent);
		setResizable(false);

		JPanel content = new JPanel(new BorderLayout(8, 8));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setBorder(new EmptyBorder(12, 12, 12, 12));

		// --- Search Header ---
		JPanel searchSection = new JPanel(new BorderLayout(4, 4));
		searchSection.setOpaque(false);

		JLabel searchLabel = new JLabel("Search Item:");
		searchLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		searchLabel.setFont(FontManager.getRunescapeSmallFont());
		searchSection.add(searchLabel, BorderLayout.NORTH);

		searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchField.setForeground(java.awt.Color.WHITE);
		searchField.setCaretColor(java.awt.Color.WHITE);
		searchField.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(4, 6, 4, 6)
		));
		searchSection.add(searchField, BorderLayout.CENTER);

		content.add(searchSection, BorderLayout.NORTH);

		// --- Search Results List ---
		searchResultsList.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchResultsList.setForeground(java.awt.Color.WHITE);
		searchResultsList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		searchResultsList.setCellRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus)
			{
				super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
				if (value instanceof ItemPrice)
				{
					ItemPrice ip = (ItemPrice) value;
					setText(ip.getName() + " (" + QuantityFormatter.formatNumber(ip.getPrice()) + " gp)");
					setBorder(new EmptyBorder(3, 6, 3, 6));
				}
				if (isSelected)
				{
					setBackground(ColorScheme.BRAND_ORANGE);
					setForeground(java.awt.Color.WHITE);
				}
				else
				{
					setBackground(ColorScheme.DARKER_GRAY_COLOR);
					setForeground(java.awt.Color.WHITE);
				}
				return this;
			}
		});

		searchResultsList.addListSelectionListener(e -> {
			if (!e.getValueIsAdjusting())
			{
				selectedItem = searchResultsList.getSelectedValue();
				if (selectedItem != null)
				{
					clientThread.invokeLater(() -> {
						long gePrice = itemManager.getItemPrice(selectedItem.getId());
						if (gePrice <= 0)
						{
							gePrice = selectedItem.getPrice();
						}
						long finalPrice = gePrice;
						SwingUtilities.invokeLater(() -> priceField.setText(String.valueOf(finalPrice)));
					});
				}
			}
		});

		JScrollPane scrollPane = new JScrollPane(searchResultsList);
		scrollPane.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		content.add(scrollPane, BorderLayout.CENTER);

		// --- Inputs: Quantity & Price ---
		JPanel bottomPanel = new JPanel(new BorderLayout(8, 8));
		bottomPanel.setOpaque(false);

		JPanel fieldsPanel = new JPanel(new GridLayout(2, 2, 6, 6));
		fieldsPanel.setOpaque(false);

		JLabel qtyLabel = new JLabel("Quantity:");
		qtyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		qtyLabel.setFont(FontManager.getRunescapeSmallFont());
		quantityField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		quantityField.setForeground(java.awt.Color.WHITE);
		quantityField.setCaretColor(java.awt.Color.WHITE);
		quantityField.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(4, 6, 4, 6)
		));

		JLabel priceLabel = new JLabel("Purchase Price (ea):");
		priceLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		priceLabel.setFont(FontManager.getRunescapeSmallFont());
		priceField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		priceField.setForeground(java.awt.Color.WHITE);
		priceField.setCaretColor(java.awt.Color.WHITE);
		priceField.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(4, 6, 4, 6)
		));

		fieldsPanel.add(qtyLabel);
		fieldsPanel.add(quantityField);
		fieldsPanel.add(priceLabel);
		fieldsPanel.add(priceField);

		bottomPanel.add(fieldsPanel, BorderLayout.NORTH);

		// Buttons
		JPanel buttonPanel = new JPanel(new GridLayout(1, 2, 8, 0));
		buttonPanel.setOpaque(false);

		JButton addButton = new JButton("Add Item");
		addButton.setBackground(ColorScheme.BRAND_ORANGE);
		addButton.setForeground(java.awt.Color.WHITE);
		addButton.addActionListener(e -> onAdd());

		JButton cancelButton = new JButton("Cancel");
		cancelButton.addActionListener(e -> dispose());

		buttonPanel.add(addButton);
		buttonPanel.add(cancelButton);
		bottomPanel.add(buttonPanel, BorderLayout.SOUTH);

		content.add(bottomPanel, BorderLayout.SOUTH);

		// Real-time search filter
		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e) { updateSearch(); }
			@Override
			public void removeUpdate(DocumentEvent e) { updateSearch(); }
			@Override
			public void changedUpdate(DocumentEvent e) { updateSearch(); }
		});

		setContentPane(content);
	}

	private void updateSearch()
	{
		String query = searchField.getText().trim();
		listModel.clear();
		if (query.length() < 2)
		{
			return;
		}

		List<ItemPrice> results = itemManager.search(query);
		int count = 0;
		for (ItemPrice item : results)
		{
			listModel.addElement(item);
			count++;
			if (count >= 50)
			{
				break;
			}
		}
	}

	private void onAdd()
	{
		if (selectedItem == null)
		{
			JOptionPane.showMessageDialog(this, "Please select an item from the list.", "No Item Selected", JOptionPane.WARNING_MESSAGE);
			return;
		}

		int quantity;
		long purchasePrice;
		try
		{
			quantity = Integer.parseInt(quantityField.getText().trim().replace(",", ""));
			if (quantity <= 0) throw new NumberFormatException();
		}
		catch (NumberFormatException e)
		{
			JOptionPane.showMessageDialog(this, "Quantity must be a positive integer.", "Invalid Quantity", JOptionPane.ERROR_MESSAGE);
			return;
		}

		try
		{
			purchasePrice = Long.parseLong(priceField.getText().trim().replace(",", ""));
			if (purchasePrice < 0) throw new NumberFormatException();
		}
		catch (NumberFormatException e)
		{
			JOptionPane.showMessageDialog(this, "Price must be a valid non-negative number.", "Invalid Price", JOptionPane.ERROR_MESSAGE);
			return;
		}

		final int itemId = selectedItem.getId();
		final String itemName = selectedItem.getName();
		final long finalPurchasePrice = purchasePrice;
		final int finalQuantity = quantity;

		clientThread.invokeLater(() -> {
			long currentPrice = itemManager.getItemPrice(itemId);
			if (currentPrice <= 0)
			{
				currentPrice = finalPurchasePrice;
			}
			plugin.addTrackedItem(itemId, itemName, finalQuantity, finalPurchasePrice, currentPrice);
		});

		dispose();
	}
}

package com.geprofittracker.ui;

