	private static final Color LOSS_COLOR = new Color(245, 80, 80);

	private final GeProfitTrackerPlugin plugin;
	private final ItemManager itemManager;
	private final ClientThread clientThread;

	private final JLabel totalCostLabel = new JLabel("0 gp");
	private final JLabel currentValueLabel = new JLabel("0 gp");
	private final JLabel netProfitLabel = new JLabel("0 gp");
	private final JLabel lastUpdatedLabel = new JLabel("Never");

