		summaryCard.setBorder(new EmptyBorder(6, 8, 6, 8));
		summaryCard.setLayout(new BoxLayout(summaryCard, BoxLayout.Y_AXIS));

		JLabel summaryTitle = new JLabel("PORTFOLIO SUMMARY");
