	private void addSummaryRow(JPanel panel, String labelText, JLabel valueLabel)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);

		JLabel label = new JLabel(labelText);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		valueLabel.setForeground(Color.WHITE);

		row.add(label, BorderLayout.WEST);
		row.add(valueLabel, BorderLayout.EAST);
		panel.add(row);
	}

	public void rebuild()
	{
		List<TrackedItem> items = plugin.getTrackedItems();
		boolean accountForTax = plugin.isAccountForGeTax();

		long totalCost = 0;
		long totalValue = 0;

		itemsListPanel.removeAll();

		if (items.isEmpty())
		{
			JPanel emptyPanel = new JPanel(new BorderLayout());
			emptyPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			emptyPanel.setBorder(new EmptyBorder(16, 8, 16, 8));

			JLabel emptyLabel = new JLabel("<html><center>No items tracked.<br>Buy on GE or click '+ Add Item' above.</center></html>", SwingConstants.CENTER);
			emptyLabel.setFont(FontManager.getRunescapeSmallFont());
			emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			emptyPanel.add(emptyLabel, BorderLayout.CENTER);

			itemsListPanel.add(emptyPanel);
		}
		else
		{
			for (TrackedItem item : items)
			{
				totalCost += item.getTotalPurchaseCost();
				totalValue += item.getTotalCurrentValue(accountForTax);
				itemsListPanel.add(new TrackedItemPanel(plugin, itemManager, item));
				itemsListPanel.add(Box.createVerticalStrut(4));
			}
		}

		long netProfit = totalValue - totalCost;

		totalCostLabel.setText(formatGp(totalCost));
		totalCostLabel.setToolTipText("Invested: " + QuantityFormatter.formatNumber(totalCost) + " gp");

		currentValueLabel.setText(formatGp(totalValue));
		currentValueLabel.setToolTipText("Current Value: " + QuantityFormatter.formatNumber(totalValue) + " gp"
			+ (accountForTax ? " (after GE tax)" : ""));

		netProfitLabel.setToolTipText("Net Profit / Loss: " + (netProfit > 0 ? "+" : "") + QuantityFormatter.formatNumber(netProfit) + " gp");
		if (netProfit > 0)
		{
			netProfitLabel.setText("+" + formatGp(netProfit));
			netProfitLabel.setForeground(PROFIT_COLOR);
		}
		else if (netProfit < 0)
		{
			netProfitLabel.setText(formatGp(netProfit));
			netProfitLabel.setForeground(LOSS_COLOR);
		}
		else
		{
			netProfitLabel.setText("0 gp");
			netProfitLabel.setForeground(Color.WHITE);
		}

		long lastUpdated = plugin.getLastPriceUpdateTime();
		if (lastUpdated > 0)
		{
			long diffSec = (System.currentTimeMillis() - lastUpdated) / 1000;
			if (diffSec < 60)
			{
				lastUpdatedLabel.setText("Just now");
			}
			else
			{
				lastUpdatedLabel.setText((diffSec / 60) + "m ago");
			}
		}
		else
		{
			lastUpdatedLabel.setText("Never");
		}

		itemsListPanel.revalidate();
		itemsListPanel.repaint();
		revalidate();
		repaint();
	}

	private static String formatGp(long gp)
	{
		if (gp >= 100_000_000 || gp <= -100_000_000)
		{
			return QuantityFormatter.quantityToStackSize(gp) + " gp";
		}
		return QuantityFormatter.formatNumber(gp) + " gp";
	}
}

