package com.geprofittracker;

import org.junit.Test;
import static org.junit.Assert.*;

public class TrackedItemTest
{
	@Test
	public void testProfitLossCalculationWithoutTax()
	{
		TrackedItem item = new TrackedItem(4151, "Abyssal whip", 2, 1_500_000, 1_600_000);
		assertEquals(3_000_000L, item.getTotalPurchaseCost());
		assertEquals(3_200_000L, item.getTotalCurrentValue(false));
		assertEquals(200_000L, item.getProfitLoss(false));
	}

	@Test
	public void testProfitLossCalculationWithTax()
	{
		// 1_600_000 current price, 1% tax = 16,000 gp tax per item -> 1_584_000 ea after tax
		// 2 items * 1_584_000 = 3_168_000 total after tax value
		// Profit = 3_168_000 - 3_000_000 = 168_000 gp
		TrackedItem item = new TrackedItem(4151, "Abyssal whip", 2, 1_500_000, 1_600_000);
		assertEquals(3_168_000L, item.getTotalCurrentValue(true));
		assertEquals(168_000L, item.getProfitLoss(true));
	}

	@Test
	public void testLossCalculation()
	{
		TrackedItem item = new TrackedItem(11802, "Armadyl godsword", 1, 10_000_000, 9_500_000);
		assertEquals(10_000_000L, item.getTotalPurchaseCost());
		assertEquals(9_500_000L, item.getTotalCurrentValue(false));
		assertEquals(-500_000L, item.getProfitLoss(false));
	}

	@Test
	public void testTaxCapAt5Million()
	{
		// Twisted bow at 1,000,000,000 gp. 1% would be 10,000,000, but cap is 5,000,000
		TrackedItem item = new TrackedItem(20997, "Twisted bow", 1, 990_000_000, 1_000_000_000);
		long valueWithTax = item.getTotalCurrentValue(true);
		assertEquals(995_000_000L, valueWithTax);
		assertEquals(5_000_000L, item.getProfitLoss(true));
	}
}
